import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';


export type Maybe<T> = T | null
export type InputMaybe<T> = T | null | undefined
export type Exact<T extends { [key: string]: unknown }> = {
  [K in keyof T]: T[K]
}
export type MakeOptional<T, K extends keyof T> = Omit<T, K> & {
  [SubKey in K]?: Maybe<T[SubKey]>
}
export type MakeMaybe<T, K extends keyof T> = Omit<T, K> & {
  [SubKey in K]: Maybe<T[SubKey]>
}
export type MakeEmpty<
  T extends { [key: string]: unknown },
  K extends keyof T,
> = { [_ in K]?: never }
export type Incremental<T> =
  | T
  | {
      [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never
    }
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string }
  String: { input: string; output: string }
  Boolean: { input: boolean; output: boolean }
  Int: { input: number; output: number }
  Float: { input: number; output: number }
  /** The builtin Any type */
  Any: { input: any; output: any }
  /**
   * Define a Relay Cursor type:
   * https://relay.dev/graphql/connections.htm#sec-Cursor
   */
  Cursor: { input: any; output: any }
  Date: { input: any; output: any }
  /**
   * {
   * "fileName": "",
   * "filePath": ""
   * }
   */
  File: { input: any; output: any }
  Int8: { input: any; output: any }
  /** The builtin Map type */
  Map: { input: any; output: any }
  /**
   * 项目合同识别信息
   * ```json
   * {
   * "contract_type": "采购合同",
   * "contract_no": "PO-202606001",
   * "party_a": {
   * "name": "北京某科技有限公司",
   * "credit_code": "9111xxxx"
   * },
   * "party_b": {
   * "name": "上海某贸易有限公司",
   * "credit_code": "9131xxxx"
   * },
   * "project_name": "达人营销项目",
   * "currency": "CNY",
   * "amount": 200000,
   * "sign_date": "2026-06-01",
   * "effective_date": "2026-06-15",
   * "expire_date": "2027-06-14",
   * "payment_terms": [
   * {
   * "stage": "预付款",
   * "ratio": 30,
   * "condition": "合同签订后"
   * },
   * {
   * "stage": "尾款",
   * "ratio": 70,
   * "condition": "验收完成后"
   * }
   * ],
   * "invoice": {
   * "required": true,
   * "type": "增值税专票"
   * },
   * "auto_renewal": false,
   * "risk_points": [
   * "未约定违约金",
   * "账期过长"
   * ]
   * }
   * ```
   */
  ProjectContractExtractedInfo: { input: any; output: any }
  /** The builtin Time type */
  Time: { input: any; output: any }
  Uint8: { input: any; output: any }
  /** The `UploadFile, // b.txt` scalar type represents a multipart file upload. */
  Upload: { input: any; output: any }
}

